import { createPaymentIntent } from '../api'

/** Shows Apple Pay when the browser supports it, and pays the cart total. */
export function ApplePayButton({ total }: { total: number }) {
  if (!('ApplePaySession' in window)) return null
  const pay = async () => {
    const intent = await createPaymentIntent(total)
    const session = new ApplePaySession(3, {
      countryCode: 'US',
      currencyCode: 'USD',
      merchantCapabilities: ['supports3DS'],
      supportedNetworks: ['visa', 'masterCard', 'amex'],
      total: { label: 'Trailhead', amount: total.toFixed(2) }
    })
    session.onpaymentauthorized = () => session.completePayment(intent.ok ? 0 : 1)
    session.begin()
  }
  return <button className="apple-pay" onClick={pay} aria-label="Pay with Apple Pay" />
}

import { CartSummary } from '../components/CartSummary'
import { ApplePayButton } from '../components/ApplePayButton'
import { useCart } from '../cart'

export function Checkout() {
  const { total } = useCart()
  return (
    <main>
      <h1>Checkout</h1>
      <CartSummary />
      <ApplePayButton total={total} />
    </main>
  )
}

import { payments } from '../providers'

/** POST /payments/intent: starts a payment for the cart total, in cents. */
export async function createPaymentIntent(req: { amount: number; currency?: string }) {
  if (!Number.isInteger(req.amount) || req.amount <= 0) throw new Error('amount must be a positive number of cents')
  const intent = await payments.intents.create({ amount: req.amount, currency: req.currency ?? 'usd', methods: ['card', 'apple_pay'] })
  return { id: intent.id, clientSecret: intent.clientSecret }
}
